[
  {
    "text": "Chat2Scenic achieves a Compilation Success Rate (CSR) of 76.42% and a Framework Accuracy (FA) of 58.17% when evaluated with State-of-the-Art Large Language Models (LLMs).",
    "topic": "Performance metrics of Chat2Scenic"
  },
  {
    "text": "Retrieval Assemble method achieves a CSR of 30.08% and an FA of 11.03%.",
    "topic": "Performance metrics of Retrieval Assemble"
  },
  {
    "text": "Retrieval full script generation method achieves a CSR of 16.26% and an FA of 10.86%.",
    "topic": "Performance metrics of Retrieval full script generation"
  },
  {
    "text": "The code for Chat2Scenic is released as open source at https://github.com/TUM-AVS/chat2scenic.",
    "topic": "Open-source availability of Chat2Scenic"
  },
  {
    "text": "Chat2Scenic is an iterative retrieval-augmented framework designed to generate scenario scripts in Domain Specific Language (DSL) for autonomous driving.",
    "topic": "Purpose of Chat2Scenic"
  }
]
